class GraphSourceProvider:
    def __init__(self, driver, database=None):
        self.driver, self.database = driver, database

    def list_sources(self):
        with self.driver.session(database=self.database) as session:
            return [self._normalize(row["source"]) for row in session.run("MATCH (s:SourceFile) RETURN s{.*} AS source ORDER BY s.id")]

    def list_signals(self):
        with self.driver.session(database=self.database) as session:
            return [self._normalize(row["signal"]) for row in session.run("MATCH (s:Signal) RETURN s{.*} AS signal ORDER BY s.id")]

    def verify_reference(self, reference):
        """Verify exact imported row or PDF chunk provenance; ambiguous IDs fail closed."""
        candidates = []
        for kind in ("record", "chunk"):
            try:
                candidates.append(self.get(kind, reference["record_id"]))
            except DomainError as exc:
                if exc.status != 404:
                    raise
        if len(candidates) != 1:
            return False
        try:
            source = self.get("source", reference["source_id"])
        except DomainError as exc:
            if exc.status == 404:
                return False
            raise
        record = candidates[0]
        return (record.get("source_id") == reference["source_id"]
                and record.get("source_version") == reference["source_version"]
                and source.get("source_version", source.get("sha256")) == reference["source_version"]
                and same_snapshot(record.get("locator"), reference["locator"])
                and reference["validation_state"] == "verified")

    def list_conflicts(self, model=None):
        with self.driver.session(database=self.database) as session:
            rows = session.run("MATCH (c:ConflictNode) WHERE $model IS NULL OR c.model = $model RETURN c{.*} AS conflict ORDER BY c.delta DESC", model=model)
            return [dict(row["conflict"]) for row in rows]

    def get(self, kind, entity_id):
        labels = {"source": "SourceFile", "record": "SourceRecord", "chunk": "DocumentChunk", "signal": "Signal"}
        if kind not in labels:
            raise DomainError(422, "Unsupported source entity kind")
        with self.driver.session(database=self.database) as session:
            rows = list(session.run(f"MATCH (s:{labels[kind]} {{id:$id}}) RETURN s{{.*}} AS entity LIMIT 2", id=entity_id))
        if not rows:
            raise DomainError(404, "Source entity not found")
        if len(rows) != 1:
            raise DomainError(503, "Source identity is ambiguous")
        entity = self._normalize(rows[0]["entity"])
        if kind == "chunk" and "locator" not in entity and entity.get("source_record_id"):
            record = self.get("record", entity["source_record_id"])
            if (record.get("source_id") != entity.get("source_id")
                    or record.get("source_version") != entity.get("source_version")):
                raise DomainError(503, "Document chunk provenance does not match its source record")
            entity["locator"] = record.get("locator", {})
        return entity


    @staticmethod
    def _normalize(properties):
        entity = dict(properties)
        # Role 01 uses source_file_id; the backend contract uses source_id.
        if "source_id" not in entity and "source_file_id" in entity:
            entity["source_id"] = entity["source_file_id"]
        for storage_key, key in (("locator_json", "locator"), ("raw_payload_json", "raw_payload"), ("evidence_links_json", "evidence_links")):
            if storage_key in entity:
                try:
                    entity[key] = json.loads(entity.pop(storage_key))
                except (json.JSONDecodeError, TypeError) as exc:
                    raise DomainError(503, "Imported source metadata is malformed") from exc
        for key in ("locator", "evidence_links"):
            if isinstance(entity.get(key), str):
                try:
                    entity[key] = json.loads(entity[key])
                except json.JSONDecodeError as exc:
                    raise DomainError(503, "Imported source metadata is malformed") from exc
        for key, expected in (("locator", dict), ("raw_payload", dict), ("evidence_links", list)):
            if key in entity and not isinstance(entity[key], expected):
                raise DomainError(503, "Imported source metadata has an invalid shape")
        if "evidence_links" in entity and any(not isinstance(link, dict) for link in entity["evidence_links"]):
            raise DomainError(503, "Imported evidence links must be objects")
        if "locator" in entity:
            # Role 01 retains unknown optional metadata as null; backend locator
            # values describe concrete anchors only. Keep original raw payload.
            entity["locator"] = {key: value for key, value in entity["locator"].items() if value is not None}
        return entity


class Role01SourceProvider(GraphSourceProvider):
    """HTTP scope adapter over Role 01's authoritative graph query implementation.

    Plural scopes expand into disjoint canonical cohorts. Unsupported filters fail
    explicitly rather than silently widening evidence retrieval.
    """

    def __init__(self, driver, database=None):
        super().__init__(driver, database)
        self.evidence = Neo4jEvidenceProvider(driver, database)

    @staticmethod
    def _scopes(scope):
        if scope is None or isinstance(scope, EvidenceScope):
            return [scope or EvidenceScope()]
        if not isinstance(scope, dict):
            raise DomainError(422, "Evidence scope must be an object")
        plural = {"regions": "region", "derivatives": "derivative", "powertrains": "powertrain"}
        if not set(scope) & (set(plural) | {"signal_ids", "topics"}):
            if set(scope) - set(EvidenceScope.__dataclass_fields__):
                raise DomainError(422, "Unsupported evidence scope filter")
            return [EvidenceScope(**scope)]
        if set(scope) - (set(plural) | {"signal_ids", "topics"}):
            raise DomainError(422, "Cannot mix singular and plural evidence scopes")
        if scope.get("signal_ids") or scope.get("topics"):
            raise DomainError(422, "Signal and topic filters are not supported by Role 01 retrieval")
        values = []
        for key, field in plural.items():
            supplied = scope.get(key, [])
            if not isinstance(supplied, list) or any(not isinstance(v, str) or not v.strip() for v in supplied):
                raise DomainError(422, "Scope filters must be lists of nonempty strings")
            canonical = [EvidenceScope(**{field: value}).query_params()[field] for value in supplied]
            values.append(list(dict.fromkeys(canonical)) or [None])
        if len(values[0]) * len(values[1]) * len(values[2]) > 100:
            raise DomainError(422, "Evidence scope has too many cohort combinations")
        return [EvidenceScope(region=r, derivative=d, powertrain=p) for r, d, p in product(*values)]

    def _search(self, method, query, scope, limit, **kwargs):
        rows = {}
        for selected in self._scopes(scope):
            for row in getattr(self.evidence, method)(query, selected, limit=limit, **kwargs):
                rows[row["id"]] = row
        return [rows[key] for key in sorted(rows)][:limit]

    def search_feedback(self, query, scope=None, limit=20):
        return self._search("search_feedback", query, scope, limit)

    def search_document_chunks(self, query, scope=None, document_kind=None, limit=6):
        return self._search("search_document_chunks", query, scope, limit, document_kind=document_kind)

    def get_source_record(self, record_id):
        return self.evidence.get_source_record(record_id)

    def _facts(self, method, scope, **kwargs):
        results = [getattr(self.evidence, method)(scope=selected, **kwargs) for selected in self._scopes(scope)]
        if len(results) == 1:
            return results[0]
        merged = dict(results[0])
        for key in ("facts", "possible_whole_line_proxy_candidates"):
            rows = {row["id"]: row for result in results for row in result.get(key, [])}
            if key in merged:
                merged[key] = [rows[rid] for rid in sorted(rows)]
        versions = sorted({v for result in results for v in result.get("source_versions", [])})
        merged.update(source_versions=versions, mixed_source_versions=len(versions) > 1,
                      scope_results=results)
        if "available_lines_in_scope" in merged:
            merged["available_lines_in_scope"] = sorted({v for result in results for v in result["available_lines_in_scope"]})
            merged["scope_gap"] = None if merged["facts"] else "No directly applicable sales facts for the requested scopes"
            merged["proxy_candidates_are_not_direct_derivative_volumes"] = bool(merged["possible_whole_line_proxy_candidates"])
        return merged

    def get_survey_facts(self, topic=None, scope=None):
        return self._facts("get_survey_facts", scope, topic=topic)

    def get_sales_facts(self, scope=None, year=2030):
        return self._facts("get_sales_facts", scope, year=year)

    def get_comment_cohort_counts(self, scope=None):
        results = [self.evidence.get_comment_cohort_counts(selected) for selected in self._scopes(scope)]
        if len(results) == 1:
            return results[0]
        merged = dict(results[0])
        for key in ("cohort_distinct_comment_count", "cohort_annotation_count"):
            merged[key] = sum(result[key] for result in results)
        for key in ("topic_bucket_distinct_comments", "topic_annotation_counts", "issue_label_distinct_comments",
                    "issue_annotation_counts", "source_label_counts"):
            merged[key] = {}
            for result in results:
                for label, count in result[key].items():
                    merged[key][label] = merged[key].get(label, 0) + count
        merged["annotation_counts_by_original_type"] = {}
        for result in results:
            for label, counts in result["annotation_counts_by_original_type"].items():
                dest = merged["annotation_counts_by_original_type"].setdefault(label, {"distinct_comments": 0, "annotation_count": 0})
                for key, count in counts.items():
                    dest[key] += count
        versions = sorted({v for result in results for v in result["source_versions"]})
        merged.update(source_versions=versions, mixed_source_versions=len(versions) > 1)
        return merged
    return canonical_json({"source_snapshots": record.get("source_snapshots", []),
        "required_assumption_ids": record.get("required_assumption_ids", []),
        "score_context": record.get("score_context"), "evidence_context": record.get("evidence_context")})


class GovernanceService:
    def __init__(self, repository, evidence_provider, audit_failure=None):
        self.repository = repository
        self.evidence_provider = evidence_provider
        self.audit_failure = audit_failure

    def event(self, state, action, entity_id, before, after, actor, rationale, entity_type=None):
        if self.audit_failure:
            self.audit_failure(action)
        return append_event(state, {"id": str(uuid.uuid4()), "entity_id": entity_id,
            "entity_type": entity_type or {"FREEZE_CREATED": "FreezeSnapshot", "RANKING_RECALCULATED": "RankingSnapshot", "SCORING_CONFIG_CREATED": "ScoringConfig", "SOURCE_IMPORTED": "SourceFile", "SIGNAL_CONSOLIDATED": "Signal", "CHALLENGE_REQUESTED": "ReviewConversation", "CHALLENGE_COMPLETED": "ReviewConversation"}.get(action, "Requirement"), "action": action, "timestamp": now(),
            "actor_id": actor[0], "actor_role": actor[1], "rationale": rationale,
            "before": copy.deepcopy(before), "after": copy.deepcopy(after)})

    def context(self, draft):
        # Resolution and source checks are outside database/model transactions.
        try:
            # Adapters own evidence resolution, never validated content or human
            # review. Isolate both directions so retained adapter references also
            # cannot change the context after it has been validated.
            context = copy.deepcopy(self.evidence_provider.resolve(copy.deepcopy(draft)))
        except DomainError:
            raise
        except (ValueError, TypeError) as exc:
            raise DomainError(422, "Evidence resolver rejected the draft") from exc
        except Exception as exc:
            raise DomainError(503, "Evidence resolver is unavailable") from exc
        if not isinstance(context, dict) or context.get("traceable") is not True:
            raise DomainError(422, "Evidence must resolve to original source versions")
        if not isinstance(context.get("score_context"), dict) or not isinstance(context.get("evidence_context"), dict) or not isinstance(context.get("verified"), bool):
            raise DomainError(422, "Evidence resolver returned an invalid authoritative context")
        required = context.get("required_assumption_ids", [])
        if not isinstance(required, list) or any(not isinstance(i, str) or not i.strip() for i in required):
            raise DomainError(422, "Evidence resolver returned invalid required assumption IDs")
        snapshots = context.get("source_snapshots", [])
        if not isinstance(snapshots, list) or any(not isinstance(item, dict) for item in snapshots):
            raise DomainError(422, "Evidence resolver returned invalid source snapshots")
        try:
            EvidencePack.model_validate(context)
            json.dumps(context, allow_nan=False)
            calculate_score(context["score_context"])
            calculate_evidence(context["evidence_context"])
        except (ValueError, TypeError, KeyError) as exc:
            raise DomainError(422, "Evidence resolver returned invalid authoritative scoring or snapshot data") from exc
        return context

    def score(self, record, context, override=None):
        record["source_snapshots"] = copy.deepcopy(context.get("source_snapshots", []))
        record["required_assumption_ids"] = copy.deepcopy(context.get("required_assumption_ids", []))
        record["score_context"] = copy.deepcopy(context["score_context"])
        record["evidence_context"] = copy.deepcopy(context["evidence_context"])
        record["scoring_policy"] = {"id": context["score_context"].get("policy_version", "v1"), "policy_version": context["score_context"].get("policy_version", "v1"), "weights": copy.deepcopy(context["score_context"].get("weights", WEIGHTS)), "fixed_reference_volume": context["score_context"].get("reference_volume"), "evidence_policy_version": "eci-v1"}
        if context["score_context"].get("reference_baseline") is not None:
            record["scoring_policy"]["reference_baseline"] = copy.deepcopy(context["score_context"]["reference_baseline"])
        record["score"] = calculate_score(context["score_context"], override=override)
        if record["score"]["policy_version"] == "v1":
            record["scoring_policy"]["weights"] = {name: factor["weight"] for name, factor in record["score"]["factors"].items()}
        record["evidence"] = calculate_evidence(context["evidence_context"])
        record["prioritization_rationale"] = context.get("prioritization_rationale", "Versioned policy v1; contributions and source references are recorded in score.")
        record["validation_state"] = "verified" if context.get("verified") else "unverified"

    def install_config(self, state, record, actor, rationale):
        config = record["scoring_policy"]
        key = config["policy_version"]
        configs = state.setdefault("configs", {})
        if key in configs and canonical_json(configs[key]) != canonical_json(config):
            raise DomainError(409, "Scoring baseline configuration differs; explicit version migration required")
        if key not in configs:
            configs[key] = copy.deepcopy(config)
            self.event(state, "SCORING_CONFIG_CREATED", key, None, config, actor, rationale)

    def ranking(self, state, actor, rationale):
        eligible = [r for r in state["requirements"].values() if r["status"] not in ("REJECTED", "POSTPONED") and r["score"]["policy_version"] == "v1"]
        ranks = rank_requirements(eligible)
        eligible.sort(key=lambda r: ranks[r["id"]])
        ranking = {"id": str(uuid.uuid4()), "timestamp": now(), "config_id": eligible[0]["score"]["policy_version"] if eligible else "v1", "configurations": {r["id"]: copy.deepcopy(r.get("scoring_policy", {})) for r in eligible}, "context": "all current active requirements", "ranks": {r["id"]: i+1 for i, r in enumerate(eligible)}, "revisions": {r["id"]: r["revision"] for r in eligible}, "scores": {r["id"]: r["score"]["effective_score"] for r in eligible}}

    def guard_identity(self, rid, request):
        if request.id is not None and request.id != rid:
            raise DomainError(422, "Route and body requirement IDs differ")
        if request.actor_role != "PM_USER" or request.actor_id.upper() == "AI_SYSTEM":
            raise DomainError(422, "A named human PM must authorize this mutation")

    def freeze(self, request):
        if request.actor_id.upper() == "AI_SYSTEM":
            raise DomainError(422, "A named human PM must authorize freeze")
        preflight = self.repository.read()
        for rid, revision in request.selections.items():
            record = preflight["requirements"].get(rid)
            if not record or record["revision"] != revision or record["status"] != "APPROVED":
                raise DomainError(409, "Freeze requires current approved revisions")
            context = self.context({k: record[k] for k in RequirementDraft.model_fields})
            if not context.get("verified") or evidence_basis(context) != evidence_basis(record):
                raise DomainError(409, "Evidence changed since approval; refresh and review")
            snapshots = context.get("source_snapshots", [])
            for link in record["evidence_links"]:
                if not any(canonical_json({k: snapshot.get(k) for k in ("source_id", "record_id", "source_version", "locator")}) == canonical_json({k: link[k] for k in ("source_id", "record_id", "source_version", "locator")}) and bool(snapshot.get("raw_payload")) for snapshot in snapshots):
                    raise DomainError(422, "Freeze requires complete pinned source snapshots for every evidence link")
        def freeze(state):
            ranking = state["rankings"][-1] if state["rankings"] else None
            if not ranking or ranking["id"] != request.expected_ranking_id:
                raise DomainError(409, "Stale ranking baseline")
            records = []
            for rid, revision in request.selections.items():
                record = state["requirements"].get(rid)
                if not record or record["status"] != "APPROVED" or record["revision"] != revision or record["approved_revision"] != revision:
                    raise DomainError(409, "Freeze requires current approved revisions")
                if ranking["revisions"].get(rid) != revision:
                    raise DomainError(409, "Approved revision is outside the ranking baseline")
                records.append(copy.deepcopy(record))
            snapshot = {"id": str(uuid.uuid4()), "timestamp": now(), "actor_id": request.actor_id, "rationale": request.rationale, "requirements": records, "ranking": copy.deepcopy(ranking), "configurations": copy.deepcopy(state.get("configs", {})), "scoring_policies": {r["id"]: copy.deepcopy(r.get("scoring_policy", {})) for r in records}, "source_snapshots": [copy.deepcopy(source) for r in records for source in r.get("source_snapshots", [])]}
            self.event(state, "FREEZE_CREATED", snapshot["id"], None, snapshot, (request.actor_id, request.actor_role), request.rationale)
            snapshot["checkpoint"] = copy.deepcopy(state["checkpoint"])
            snapshot["audit"] = audit_bundle(state, snapshot["checkpoint"])
            state["freezes"][snapshot["id"]] = snapshot
            return snapshot
        return self.repository.write(freeze)

